SET('zemmour','accise',-9.0,-12,-8.2,"Même base que la TICPE de Le Pen : volumes 2025 (gazole 32 Mm³, dont 7,6 Mm³ remboursés aux poids lourds et 0,8 Mm³ aux autocars ; essences 15,6 Mm³) × tarifs 2026 (gazole 60,75 €/hl ; SP95-E5 69,02 et E10 67,02, moyenne 68,02). Un tiers : gazole non remboursé 23,6 Mm³ × 20,25 €/hl = 4,78 ; poids lourds : le tarif national (40,50) passe sous leur tarif net (45,19), perte 4,69 €/hl × 7,57 Mm³ = 0,36 ; autocars : tarif net (39,19) inchangé, 0 ; essences 15,6 Mm³ × 22,67 €/hl = 3,54 ; total 8,67 aux tarifs normaux. Calage sur les recettes 2025 publiées (CPO : 17,3 + 9,9 = 27,2 Md€, contre 28,7 aux tarifs normaux pour les mêmes volumes : tarifs réduits E85, E10, B100, Corse, taxis) : × 0,948 = 8,2 ; + TVA assise sur cette part d'accise, à mi-chemin entre 0 (entreprises) et 20 % : 0,8 → ≈ −9,0. Borne haute : accise seule (−8,2) ; borne basse : chiffre du camp (−12)",method='ascendant',inputs=[{'label': "Accise 2025 sur le gazole et l'essence", 'value': "17,3 + 9,9 = 27,2 Md€ (27 Mt de gazole, 11,8 Mt d'essence)", 'source': 'Conseil des prélèvements obligatoires (Cour des comptes), juin 2026, p. 77', 'url': 'https://www.ccomptes.fr/sites/default/files/2026-06/20260603-Quel-avenir-pour-la-fiscalite-de-l-energie.pdf'}, {'label': "Partage de l'accise en 2025", 'value': '43,2 Md€ bruts toutes énergies, dont 14,4 Md€ aux collectivités', 'source': 'Conseil des prélèvements obligatoires, juin 2026, p. 52', 'url': 'https://www.ccomptes.fr/sites/default/files/2026-06/20260603-Quel-avenir-pour-la-fiscalite-de-l-energie.pdf'}, {'label': 'Accise sur les énergies nette, part État', 'value': '25,2 Md€ en 2025 ; 23,5 Md€ au PLF 2027, dont « accise sur les carburants » 16,3 Md€', 'source': 'Projet de loi de finances pour 2027 (exposé général et État A)', 'url': 'https://www.assemblee-nationale.fr/dyn/17/textes/l17b3210_projet-loi.pdf'}, {'label': 'Livraisons de carburants (année mobile à septembre 2026)', 'value': 'supercarburants (SP95-E10, SP95-E5, SP98, E85) 15 638 milliers de m³ ; gazoles routiers 30 190', 'source': 'DGEC, Cours, prix et marges des produits pétroliers, 23/10/2026', 'url': 'https://www.ecologie.gouv.fr/sites/default/files/documents/NPG-2026.10.23.pdf'}, {'label': 'Tarifs 2026, remboursements, volumes 2025', 'value': 'repris de la fiche TICPE de Le Pen (Douanes, Voies et moyens tome II, CNR, CPDP)', 'source': 'Fiche ticpe (Le Pen)', 'url': 'https://www.douane.gouv.fr/sites/default/files/ba_files/da/2026-02/BOD%20DetT%20mars%202026.pdf'}, {'label': 'Coût annoncé', 'value': '12 Md€ de manque à gagner', 'source': 'combienjegagne.fr (camp)', 'url': 'https://combienjegagne.fr/'}]+[i for i in M('zemmour','accise')['claude']['inputs'] if 'douane' in (i.get('url') or '') or 'Livraisons' in i.get('label','') or 'Remboursement' in i.get('label','')])
SET('le-pen','ticpe',-2.1,-3.9,-1.9,"Même base que l'accise de Zemmour : écart de tarif 2026 − 2017 × volumes 2025 (inchangé : gazole 23,6 Mm³ × 6,33 = 1,49 ; essences 15,6 Mm³ × 3,22 = 0,50) ; calage sur les recettes 2025 publiées (CPO 27,2 / 28,7 aux tarifs normaux = 0,948) : 1,99 × 0,948 = 1,89 ; + fioul domestique 4 Mm³ × 4,50 = 0,18 (hors calage, absent des chiffres du CPO) ; accise ≈ 2,07 ; + TVA à mi-chemin entre 0 et 5,5 % : 0,06 → ≈ −2,1. Borne haute : volumes 2030 si les tendances 2025 continuent (−1,9) ; borne basse : chiffre du camp (−3,9), hors calcul",method='ascendant',inputs=[{'label': "Accise 2025 sur le gazole et l'essence", 'value': '17,3 + 9,9 = 27,2 Md€', 'source': 'Conseil des prélèvements obligatoires (Cour des comptes), juin 2026', 'url': 'https://www.ccomptes.fr/sites/default/files/2026-06/20260603-Quel-avenir-pour-la-fiscalite-de-l-energie.pdf'}, {'label': 'Ligne du contre-budget (2027)', 'value': '3,9 Md€', 'source': "Groupe RN à l'Assemblée nationale, contre-budget 2027 (dossier publié sur deputes-rn.fr)", 'url': 'https://back.deputes-rn.fr/wp-content/uploads/2026/10/GRN-CONTRE-BUDGET-2027-DOSSIER.pdf'}]+[i for i in M('le-pen','ticpe')['claude']['inputs'] if 'douane' in (i.get('url') or '') or 'Livraisons' in i.get('label','') or 'Remboursement' in i.get('label','')])
