# S145 : suppression ou fusion de la plupart des agences et opérateurs (missions reprises par l'État) : même valeur pour les trois candidats qui la
# proposent (Le Pen, Retailleau, Lisnard), tirée du seul chiffrage indépendant de ce périmètre (commission d'enquête du Sénat, rapport n° 807, 2025) :
# fonctions support des opérateurs 2,7 Md€ (10 % des charges de personnel, 14 Md€, et de fonctionnement, 13,2 Md€), réduites de 20 % = 0,54 Md€.
# Double compte vérifié : ces 0,54 comprennent des économies de personnel, déjà comptées dans les postes supprimés de chaque plan (agents des
# agences compris) ; on ne garde que la part hors personnel, la même pour les trois : 0,54 × 13,2/27,2 = 0,26 (borne basse 0, réduction jugée
# « très volontariste » par le Sénat ; borne haute 1,06 = 8 % des 13,2 Md€ de fonctionnement). Montants des camps (RN 3,4 Md€ en 2027, Retailleau
# 12,5 Md€ en 2032) : chiffres de camp, non comptés au-delà. Philippe (« regrouper les opérateurs », sans source de 2026) et Zemmour (agences
# nommées, autre périmètre) : registre, rien de compté.
SEN807="https://www.senat.fr/rap/r24-807-1/r24-807-122.html"
AGF="agences et opérateurs supprimés ou fusionnés, missions reprises : 0,26 (valeur commune : part hors personnel, 13,2 Md€ de fonctionnement sur 27,2 Md€ de charges, de l'économie chiffrée par la commission d'enquête du Sénat en 2025 sur les fonctions support des opérateurs, 2,7 Md€ réduits de 20 % = 0,54 ; la part de personnel est dans les postes supprimés)"
IN_AG={"label":"Agences et opérateurs : économie chiffrée par le Sénat","value":"fonctions support des opérateurs (hors universités et recherche) : 10 % des charges de personnel (≈ 14 Md€) et de fonctionnement (13,2 Md€), soit 2,7 Md€ ; « une réduction de 20 % du coût des fonctions support, ce qui paraît très volontariste […], apporterait donc une économie de l'ordre de 540 millions d'euros » ; −8 % des charges de personnel et de fonctionnement : 2,2 Md€, « pas réellement à missions constantes »","source":"Sénat, commission d'enquête sur les agences, opérateurs et organismes consultatifs de l'État, rapport n° 807 (2024-2025)","url":SEN807}
AGN="Agences : valeur commune de 0,26 Md€, la même chez Le Pen, Retailleau et Lisnard : part hors personnel (13,2 Md€ de fonctionnement sur 27,2 Md€ de charges) de l'économie chiffrée par la commission d'enquête du Sénat en 2025 (fonctions support des opérateurs réduites de 20 % : 0,54 Md€), la part de personnel étant déjà dans les postes supprimés ; borne basse 0 (réduction jugée « très volontariste » par le Sénat) ; borne haute 1,06 (−8 % des 13,2 Md€ de fonctionnement des opérateurs). Le montant annoncé par le camp est un chiffre de camp, non compté au-delà."
RNCB="https://back.deputes-rn.fr/wp-content/uploads/2026/10/GRN-CONTRE-BUDGET-2027-DOSSIER.pdf"
# Le Pen : le nombre de postes (≈ 200 000) n'est donné par aucune source qui parle pour la candidate (contre-budget, site du RN, entretiens de
# Le Pen ou de Bardella) : seul un site (FranceTransactions, 6/10/2026) rapporte 85 000 postes dans les agences et 116 000 dans les collectivités
# d'ici 2032 d'après le député J.-P. Tanguy. Même règle que pour Lisnard avant le 28/10 : partie postes non chiffrable, fourchette indicative en
# note, hors total. La partie agences garde la valeur commune (même mesure, même valeur chez les trois : règle n° 1).
WEAK.append('francetransactions.com')
m=M('le-pen','etat'); k=m['claude']; assert k['formula']==POST+" ; 200 000 postes × 70 % × 30,8 k€ = 4,3 + agences ≈ 0,7 → +5 Md€" and k['central']==5
assert m['proposal']=="Supprimer la plupart des agences, ~200 000 postes publics, fin des intercommunalités et métropoles." and m['claimed_md']==20.7
SET('le-pen','etat',0.26,0,1.06,"Agences et opérateurs supprimés ou fusionnés, missions reprises : 0,26 Md€ (valeur commune : part hors personnel, 13,2 Md€ de fonctionnement sur 27,2 Md€ de charges, de l'économie chiffrée par la commission d'enquête du Sénat en 2025 sur les fonctions support des opérateurs, 2,7 Md€ réduits de 20 % = 0,54) ; borne basse 0, borne haute 1,06. Postes : non chiffrable, hors total (nombre non publié par une source qui parle pour la candidate : le contre-budget n'en donne pas et n'inscrit qu'un « ajustement des effectifs » des collectivités de 0,8 Md€ en 2027, chiffre du camp sous 1 Md€, non compté) ; fourchette indicative en note, même règle que pour Lisnard avant la publication de son nombre de postes",method='ascendant',
    proposal="Supprimer la plupart des agences et opérateurs de l'État, réduire les effectifs publics par le non-remplacement de départs (nombre de postes non publié par la candidate), fin des intercommunalités et métropoles.",
    claimed="Agences et opérateurs : 3,4 Md€ en 2027 ; effectifs des collectivités : 0,8 Md€ en 2027 (contre-budget 2027 du groupe RN, sans nombre de postes)",
    note="Postes, indicatif (hors total) : si les ≈ 201 000 postes non renouvelés d'ici 2032 (85 000 dans les agences et organismes, 116 000 dans les collectivités), rapportés par un seul site d'après le député J.-P. Tanguy lors de la présentation du contre-budget (6/10/2026), étaient repris par la candidate, la règle commune donnerait ≈ +4,3 Md€ en 2030 (200 000 × 70 % × 30,8 k€), jusqu'à +6,2 si le plan était entièrement réalisé. "+AGN+" Contre-budget du RN : « suppressions et réinternalisations d'agences et d'opérateurs » 3,4 Md€ en 2027, sans liste. Le simulateur francebudget.fr (13,5 Md€ en 2032) ne sert plus de borne (source faible).")
m['claimed_md']=4.2
n0=len(k['inputs']); k['inputs']=[IN_AG if i['label']=="Agences à missions constantes / −8 %" else i for i in k['inputs']]; assert IN_AG in k['inputs'] and len(k['inputs'])==n0
k['inputs']+=[{"label":"Lignes du contre-budget (2027)","value":"« Suppressions et réinternalisations d'agences et d'opérateurs » 3,400 Md€ ; « Ajustement des effectifs à la suite de la rationalisation des compétences des collectivités » 0,800 Md€ ; aucun nombre de postes","source":"Groupe RN à l'Assemblée nationale, contre-budget 2027 (annexe, « Postes d'économies et de dépenses »)","url":RNCB},
    {"label":"Nombre de postes rapporté (non retenu)","value":"« Jean-Philippe Tanguy chiffre à 85 000 le nombre de postes qui ne seraient pas renouvelés » dans les agences et organismes d'ici 2032 ; « Le parti estime pouvoir ne pas renouveler 116 000 postes dans les collectivités territoriales d'ici 2032 » ; seule source trouvée, ne cite pas la candidate","source":"FranceTransactions (6/10/2026), compte rendu de la présentation du contre-budget","url":"https://www.francetransactions.com/actus/actualites-socio-economiques/proposition-rn-budget-2027.html"}]
sp=C['le-pen']['sim']; assert sp['fonctionnaires']=="Au moins 200 000 postes supprimés en cinq ans (collectivités, agences, organismes)."
sp['fonctionnaires']="Suppression de la plupart des agences et non-remplacement de départs dans les agences et les collectivités (nombre de postes non publié par la candidate)."
t0=C['le-pen']['claude_total']; t0['missing']+=", postes publics non remplacés (nombre non publié par la candidate ; ≈ 201 000 d'ici 2032 selon un seul site citant un député RN : fourchette indicative dans la fiche), agences et opérateurs au-delà de la valeur commune (3,4 Md€ en 2027, chiffre du camp)"
# Retailleau : même valeur pour les agences ; bornes de la partie postes calculées comme pour les 400 000 postes de Lisnard
RFP="https://www.avecretailleau.fr/api/media/file/20261011_Fiches_presse_comptes_publics_mise_en_page%20(1).pdf"
m=M('retailleau','etat'); k=m['claude']; assert k['formula']==POST+" ; 400 000 postes × 70 % × 30,8 k€ = 8,6 + agences 1,6 + carence 0,1 ≈ +10,3 Md€" and m['claimed']=="25 Md€ (400 000 départs non remplacés) + 12,5 Md€ (agences), cumulés d'ici 2032"
SET('retailleau','etat',9.0,5.3,13.5,POST+" ; 400 000 postes × 70 % × 30,8 k€ = 8,62 + "+AGF+" + 3 jours de carence 0,11 ≈ +9,0 Md€. Bornes de la partie postes comme pour les 400 000 postes de Lisnard : un départ à la retraite sur trois non remplacé sur 3,5 ans (5,17), plan entièrement réalisé en 2030 (12,3) ; agences 0 à 1,06 ; d'où 5,3 à 13,5",method='ascendant',
    claimed="25 Md€ (400 000 départs non remplacés) et 12,5 Md€ (agences et opérateurs) par an en 2032",
    note="Camp (fiche 3 du plan du 12/10/2026, niveaux de 2032) : postes 25 Md€ ; agences 12,5 Md€ (contrats non renouvelés et départs volontaires des opérateurs 5, structures 4, concours recentrés 3,5) ; carence surévaluée (3 Md€ annoncés, 0,1 mesuré). "+AGN)
n0=len(k['inputs']); k['inputs']=[IN_AG if i['label']=='Agences' else i for i in k['inputs']]; assert IN_AG in k['inputs'] and len(k['inputs'])==n0
k['inputs'].append({"label":"Agences et opérateurs (fiche 3 du plan)","value":"« Les 1 153 agences, comités et opérateurs (Sénat, rapport n° 807, 2025) supprimés ou rapatriés » ; contrats non renouvelés et départs volontaires, hors départs en retraite (opérateurs) 5,0 + agences et opérateurs : structures (4), concours recentrés (3,5) 7,5 = 12,5 Md€ en 2032","source":"Fiches presse du camp (12/10/2026), fiche 3","url":RFP})
t0=C['retailleau']['claude_total']; t0['missing']+=", agences et opérateurs au-delà de la valeur commune (contrats non renouvelés et départs volontaires 5, structures 4, concours recentrés 3,5 ; niveaux 2032, chiffres du camp)"
# Lisnard : même valeur pour les agences (ARS, DREAL, DDTM nommées : missions reprises, pas d'économie propre publiée ni de chiffrage indépendant)
m=M('lisnard','fonction'); k=m['claude']; f0=k['formula']; assert k['central']==8.6 and f0.endswith("400 000 × 30,8 k€ ≈ +12,3. Agences, ARS et DREAL : économie propre non publiée, non comptée en plus des postes")
for a0 in (" ≈ +8,6 Md€ (même calcul que les 400 000 postes de Retailleau)","≈ +5,2 ; borne haute"): assert f0.count(a0)==1, a0
SET('lisnard','fonction',8.9,5.2,13.4,f0.replace(" ≈ +8,6 Md€ (même calcul que les 400 000 postes de Retailleau)"," = 8,62 (même calcul que les 400 000 postes de Retailleau) + "+AGF+" ≈ +8,9 Md€")
    .replace("≈ +5,2 ; borne haute","≈ +5,2, agences 0 ; borne haute")
    .replace("≈ +12,3. Agences, ARS et DREAL : économie propre non publiée, non comptée en plus des postes","≈ +12,3, + agences 1,06 = 13,4. ARS, DREAL et DDTM nommées par le candidat : missions reprises, ni économie propre publiée ni chiffrage indépendant au-delà de la valeur commune"),
    note=k['note']+" "+AGN)
k['inputs']+=[IN_AG,{"label":"Agences visées","value":"« on supprimera l'essentiel de ces machins. Il faudra garder quelques agences qui sont des garantes de l'indépendance » (Le Crayon, 11/10/2026) ; « environ 1 200 organismes publics ont été créés en vingt-cinq ans » ; sont nommées les directions régionales de l'environnement, les directions départementales des territoires et de la mer et les agences régionales de santé","source":"Nouvelle Énergie, « Quelles économies propose David Lisnard ? » (mis à jour le 16/10/2026)","url":"https://www.unenouvelleenergie.fr/questions/quelles-economies-david-lisnard-propose-t-il-et-ou-exactement/"}]
# S139 : règle générale, dans les deux sens et pour les 8 : un prélèvement sur les entreprises déductible du bénéfice imposable est compté net de
# l'impôt sur les sociétés qu'il fait varier, à 20 % (17,5 % en borne), en entier en 2030, sauf si le chiffrage retenu est déjà net. Tous les
# chiffrages publiés trouvés le comptent ainsi (Gouvernement : PLF 2021, 2023 et 2024 ; Cour des comptes et CPO 2025 ; Institut Montaigne 2022 et
# 2024 ; CAE 2019), comme l'impôt sur le revenu récupéré des fiches CSG. Pas pour l'impôt sur les sociétés lui-même ni pour un impôt non déductible
# (TVA, récupérée par les entreprises). Inventaire des fiches : registre S139 et PR.
EVP24="https://www.assemblee-nationale.fr/dyn/content/download/705211/file/Evaluations%20pr%C3%A9alables%20des%20articles%20du%20projet%20de%20loi.pdf"
CPO25="https://www.ccomptes.fr/sites/default/files/2025-09/20250922-Tracer-cadre-fiscal-et-social-pluriannuel%20pour-industrie-francaise.pdf"
IN_IS=[{"label":"Méthode du Gouvernement (étalement de la suppression de la CVAE)","value":"« Les impôts de production étant déductibles du résultat imposable, le coût net pour l'État de la présente mesure tient compte de l'impact sur les recettes d'impôt sur le revenu (IR) et d'impôt sur les sociétés (IS), via l'application d'un taux moyen d'IR/IS de 20 % » ; 70 % de l'effet dès la première année (« cinquième acompte »)","source":"Projet de loi de finances pour 2024, évaluations préalables, article 8 (p. 196)","url":EVP24},
       {"label":"Suppression de la C3S (Conseil des prélèvements obligatoires)","value":"effet brut −5 361 M€ ; retour d'impôt sur les sociétés +938 M€ (taux effectif avant crédits d'impôt de 17,5 %) ; effet net −4 423 M€","source":"Conseil des prélèvements obligatoires (Cour des comptes), « Tracer un cadre fiscal et social pluriannuel pour l'industrie française », septembre 2025, p. 134-135, tableau 15","url":CPO25}]
IN_ISC={"label":"Cotisations patronales : retour d'impôt sur les sociétés (Conseil des prélèvements obligatoires)","value":"« Lorsque l'incidence porte sur les entreprises, l'effet retour sur l'impôt sur les sociétés est calculé en utilisant le taux implicite moyen de 17,5 % avant crédit d'impôts » ; tableau 18 : déduction de cotisations patronales sur les heures supplémentaires, 860 M€, retour d'impôt sur les sociétés jusqu'à 151 M€","source":"Conseil des prélèvements obligatoires (Cour des comptes), septembre 2025, p. 137-138","url":CPO25}
ISR="impôt sur les sociétés récupéré : ces prélèvements sont déductibles du bénéfice imposable, et tous les chiffrages publiés trouvés comptent ce retour (Gouvernement, Cour des comptes, Institut Montaigne, Conseil d'analyse économique) ; règle commune, la même dans les deux sens pour tout prélèvement déductible : 20 % (taux retenu par le Gouvernement, l'Institut Montaigne et le CAE ; 17,5 %, taux de la Cour des comptes, en borne basse), en entier en 2030, comme l'impôt sur le revenu récupéré des fiches CSG"
ISN="Coût net de l'"+ISR+"."
def _isnet(cid,mid,c,l,h,f,note=None,inputs=IN_IS):
    k=M(cid,mid)['claude']; assert PRODN in k['note'], (cid,mid)
    SET(cid,mid,c,l,h,f,note=(note or k['note']).replace(PRODN,ISN)); k['inputs']=k['inputs']+inputs
PRODF2="Rendements officiels : C3S 5,36 Md€ (prévision 2026, CCSS) + CFE 8,38 Md€ (produit 2025, DGCL) = 13,74, moins l'impôt sur les sociétés récupéré (20 %, règle commune) = −11,0 Md€ ; CVAE : 0 (déjà supprimée par la loi en 2030, règle commune). Borne basse −11,7 : C3S prévue en 2027 (5,47) + CFE 2025 accrue de sa hausse de 2025 (+4,4 %) = 14,22, impôt récupéré au taux de la Cour des comptes (17,5 %) ; borne haute −10,7 : rendements de l'année précédente (C3S 2025 5,34 + CFE 2024 8,03 = 13,36), impôt récupéré à 20 %. Produit brut de la CFE : les dégrèvements payés par l'État (qui disparaîtraient) et les frais de gestion perçus par l'État (perdus) ne sont pas chiffrés ici et jouent en sens contraire"
k=M('le-pen','production')['claude']; a0="Le contre-budget compte aussi 4,27 Md€ de « retour d'IS lié à la baisse des impôts de production » : non compté. "; assert k['note'].startswith(a0) and k['central']==-13.7
_isnet('le-pen','production',-11.0,-11.7,-10.7,PRODF2,note=k['note'].replace(a0,"Le contre-budget compte 4,27 Md€ de « retour d'IS lié à la baisse des impôts de production » (taux normal de 25 % appliqué à 17,1 Md€, CVAE comprise) : chiffre du camp, non retenu ; la fiche compte ce retour avec la règle commune. "))
k=M('zemmour','production')['claude']; a0="(CVAE retirée, sans impôt sur les sociétés récupéré), elle vaudrait −26,4 (30,4 − 4)"; assert a0 in k['note'] and k['central']==-13.7
_isnet('zemmour','production',-11.0,-11.7,-10.7,"Même calcul que Le Pen : "+PRODF2[0].lower()+PRODF2[1:],note=k['note'].replace(a0,"(CVAE retirée, impôt sur les sociétés récupéré à 20 %), elle vaudrait −21,1 ((30,4 − 4) × 0,8)"))
assert M('lisnard','impots')['claude']['central']==-5.4 and M('retailleau','production')['claude']['central']==-10.1
_isnet('lisnard','impots',-4.3,-4.5,-4.3,"C3S : 5,36 Md€ (prévision 2026, CCSS, même base que Le Pen, Zemmour et Retailleau), moins l'impôt sur les sociétés récupéré (20 %, règle commune) → −4,3 ; borne basse : prévision 2027 (5,47), impôt récupéré à 17,5 % → −4,5 ; borne haute : 2025 (5,34) à 20 % → −4,3. CVAE : 0 (déjà supprimée par la loi)")
IN_FS={"label":"Forfait social : déductible du bénéfice imposable","value":"« Au plan fiscal, l'administration a admis la déductibilité de cette contribution du résultat imposable »","source":"CMS Francis Lefebvre, « Le forfait social est exclu de l'assiette du CIR selon l'administration » (29/04/2015)","url":"https://cms.law/fr/fra/a-la-une/le-forfait-social-est-exclu-de-l-assiette-du-cir-selon-l-administration"}
_isnet('retailleau','production',-8.0,-13.2,-6.4,"C3S 5,36 (rendement officiel 2026, CCSS, même base que Le Pen, Zemmour et Lisnard) + forfait social 2,8 + CFE industrielle 1,9 (détail du camp) = 10,06, moins l'impôt sur les sociétés récupéré (20 %, règle commune ; les trois prélèvements sont déductibles du bénéfice) = −8,0 Md€ ; bornes de la fiche (−16 et −8) nettes de la même façon (17,5 % et 20 %) : −13,2 et −6,4 (CVAE retirée : déjà supprimée par la loi ; heures au-delà de 1 623 heures exonérées : fiche à part)",inputs=IN_IS+[IN_FS])
# cotisations patronales (Retailleau) : montant de cotisations en moins publié par le camp (fiche 14), brut comme les 15 Md€ d'impôts de production du même plan
m=M('retailleau','cotisations'); k=m['claude']; f0=k['formula']; assert k['central']==-15.0 and k['low']==-15.0 and k['high']==-10.5
a0="Baisse annoncée : 15 Md€ de cotisations patronales (plan du 12/10/2026, montants « entreprises » annuels : les 15 Md€ d'impôts de production correspondent au rendement annuel des taxes visées). "; a1="fait l'objet d'une fiche à part (−4,3) ; borne haute : 70 % en 2030 (−10,5)"
assert f0.startswith(a0) and f0.endswith(a1)
SET('retailleau','cotisations',-12.0,-12.4,-8.4,"Baisse annoncée : 15 Md€ de cotisations patronales (plan du 12/10/2026, fiche 14 : « Cotisations patronales sur toute l'échelle des salaires 15,0 », montant de cotisations en moins, comme les 15 Md€ d'impôts de production du même plan correspondent au rendement annuel des taxes visées), moins l'impôt sur les sociétés récupéré (les cotisations patronales sont déductibles du bénéfice ; règle commune des prélèvements déductibles : 20 %, 17,5 % en borne basse, taux retenu par le Conseil des prélèvements obligatoires quand la baisse profite aux entreprises) : −15 × 0,8 = −12,0 Md€. "+f0[len(a0):-len(a1)]+"fait l'objet d'une fiche à part ; borne basse : impôt récupéré à 17,5 % (−12,4) ; borne haute : 70 % en 2030, net (−8,4)")
k['inputs']=k['inputs']+[IN_ISC,{"label":"Plan du candidat (fiche 14)","value":"« Entreprises : 30 Md€ » : « Cotisations patronales sur toute l'échelle des salaires 15,0 » ; « Impôts de production supprimés 15,0 » (Md€ 2032)","source":"Fiches presse du camp (12/10/2026), fiche 14","url":RFP}]
k=M('retailleau','menages')['claude']; a0="la même lecture vaudrait pour les cotisations patronales : −12,0 et −10,5."; assert k['note'].count(a0)==1
k['note']=k['note'].replace(a0,"la même lecture vaudrait pour les cotisations patronales : −12,0 et −8,4 (cotisations patronales nettes de l'impôt sur les sociétés récupéré).")
# seuil « zéro cotisation » (Retailleau) : « restituer 4,3 milliards d'euros aux entreprises » (cotisations patronales, déductibles)
k=M('retailleau','seuil_zero_cotisation')['claude']; a0="Coût statique annoncé par le camp sur les heures supplémentaires existantes (4,3 Md€ rendus aux entreprises) ; autofinancement par les heures nouvelles non compté (effet de comportement non documenté) ; ±50 %"
assert k['formula']==a0 and k['central']==-4.3
SET('retailleau','seuil_zero_cotisation',-3.4,-5.4,-1.8,"Coût statique annoncé par le camp sur les heures supplémentaires existantes (« restituer 4,3 milliards d'euros aux entreprises » : cotisations patronales, déductibles du bénéfice ; côté salarié, les cotisations sont déjà en grande partie exonérées), moins l'impôt sur les sociétés récupéré (20 %, règle commune) = −3,4 ; autofinancement par les heures nouvelles non compté (effet de comportement non documenté) ; ±50 %, nets de l'impôt récupéré (17,5 % et 20 %) : −5,4 et −1,8")
k['inputs']=k['inputs']+[{"label":"Ce que rend la mesure","value":"« La mesure permettrait d'abord de restituer 4,3 milliards d'euros aux entreprises sur les heures supplémentaires déjà réalisées » ; aujourd'hui, « pour le salarié : exonération de cotisations à hauteur de 11,31 % du salaire brut »","source":"Les Républicains, livret « Le travail gagnant » (janvier 2026), p. 20-21","url":"https://republicains.fr/wp-content/uploads/2026/01/51705_LesRepublicains_Brochures_A5-40P_DEF.pdf"},IN_ISC]
# accises sur les carburants (Le Pen, Zemmour) : part payée par les entreprises, déductible ; la moitié, même hypothèse « à mi-chemin » que pour la TVA
ISA=" Impôt sur les sociétés récupéré (règle commune des prélèvements déductibles) : l'accise payée par les entreprises est déductible de leur bénéfice ; il est compté sur la moitié de l'accise, la même hypothèse « à mi-chemin » que pour la TVA (part des entreprises non publiée par une source officielle : registre), à 20 % (17,5 % en borne basse), de la même façon chez Le Pen et Zemmour."
k=M('le-pen','ticpe')['claude']; a0="; + TVA à mi-chemin entre 0 et 5,5 % : 0,06 → ≈ −2,1. Borne haute : volumes 2030 si les tendances 2025 continuent (−1,9) ; borne basse : chiffre du camp (−3,9), hors calcul"
assert k['formula'].endswith(a0) and k['central']==-2.1
SET('le-pen','ticpe',-1.9,-3.6,-1.7,k['formula'][:-len(a0)]+"; + TVA à mi-chemin entre 0 et 5,5 % : 0,06 = 2,13 ; moins l'impôt sur les sociétés récupéré sur la part de l'accise payée par les entreprises (la moitié, comme pour la TVA ; 20 %, règle commune) : 2,07 × 50 % × 20 % = 0,21 → ≈ −1,9. Borne haute : volumes 2030 si les tendances 2025 continuent (−1,9 brut, −1,7 net) ; borne basse : chiffre du camp (−3,9), hors calcul, net au taux de 17,5 % sur la moitié (−3,6)",
    note=k['note']+ISA)
